import { test, expect } from '@playwright/test';

test.describe('Empty API Response Handling', () => {
  let testPage: string;

  test.beforeEach(async ({ page }) => {
    testPage = 'data:text/html,<html><body><div id="results"></div><button id="search">Search</button></body></html>';
    await page.goto(testPage);
  });

  test('should display "No results found" message when API returns empty list', async ({ page }) => {
    // Mock the API to return an empty list
    await page.route('**/api/search*', (route) => {
      route.abort('failed');
    });

    // Set up the page with search functionality
    await page.evaluate(() => {
      const resultsDiv = document.getElementById('results');
      const searchBtn = document.getElementById('search');

      if (searchBtn) {
        searchBtn.addEventListener('click', async () => {
          try {
            const response = await fetch('/api/search?q=test');
            const data = await response.json();

            if (!data.items || data.items.length === 0) {
              resultsDiv!.innerHTML = '<p>No results found</p>';
            } else {
              resultsDiv!.innerHTML = data.items.map((item: any) => `<div>${item.name}</div>`).join('');
            }
          } catch (error) {
            resultsDiv!.innerHTML = '<p>No results found</p>';
          }
        });
      }
    });

    // Mock successful API call with empty results
    await page.route('**/api/search*', (route) => {
      route.continue();
    });

    await page.route('**/api/search*', (route) => {
      route.abort('failed');
    });

    // Re-setup with proper mock
    await page.route('**/api/search*', (route) => {
      route.respond({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ items: [] })
      });
    });

    // Click search button
    await page.getByRole('button', { name: 'Search' }).click();

    // Wait for the message to appear
    await page.waitForTimeout(500);

    // Verify the "No results found" message is displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();
  });

  test('should display results when API returns non-empty list', async ({ page }) => {
    // Set up the page with search functionality
    await page.evaluate(() => {
      const resultsDiv = document.getElementById('results');
      const searchBtn = document.getElementById('search');

      if (searchBtn) {
        searchBtn.addEventListener('click', async () => {
          try {
            const response = await fetch('/api/search?q=test');
