              resultsDiv!.innerHTML = data.items.map((item: any) => `<div class="result-item">${item.name}</div>`).join('');
            }
          } catch (error) {
            resultsDiv!.innerHTML = '<p>No results found</p>';
          }
        });
      }
    });

    // Mock API to return results
    await page.route('**/api/search*', (route) => {
      route.respond({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          items: [
            { name: 'Result 1' },
            { name: 'Result 2' },
            { name: 'Result 3' }
          ]
        })
      });
    });

    // Click search button
    await page.getByRole('button', { name: 'Search' }).click();

    // Wait for results to load
    await page.waitForTimeout(500);

    // Verify results are displayed
    const resultItems = page.locator('.result-item');
    await expect(resultItems).toHaveCount(3);

    // Verify "No results found" message is NOT displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).not.toBeVisible();
